#include "elit21/shopify/webhooks/ProductWebhookHandler.h"
namespace elit21::shopify::webhooks {ProductWebhookHandler::ProductWebhookHandler():platform::BusinessComponent("ProductWebhookHandler","Persistent Shopify webhook domain handler",platform::BusinessComponentSpec{"shopify","handle_webhook",{},true,false,16U*1024U*1024U}){}ProductWebhookHandler::ProductWebhookHandler(Database&database):ProductWebhookHandler(){database_=&database;}Result<void>ProductWebhookHandler::handle(const ShopifyWebhook&event){if(!database_)return Result<void>::failure("ProductWebhookHandler is not bound to Database");return persistWebhookTask(*database_,event,{ShopifyWebhookTopic::products_update,ShopifyWebhookTopic::products_delete});}platform::OperationResult ProductWebhookHandler::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["database_bound"]=database_?1.0:0.0;r.attributes["handler"]="ProductWebhookHandler";return r;}}
